let D,range="28";const REFRESH_MS=20*60*1000,$=s=>document.querySelector(s),fmt=n=>new Intl.NumberFormat("en-IN").format(Math.round(Number(n)||0)),clock=s=>Math.floor((Number(s)||0)/60)+":"+String(Math.round((Number(s)||0)%60)).padStart(2,"0");
async function getJson(url){const r=await fetch(`${url}?t=${Date.now()}`,{cache:"no-store"}),data=await r.json();if(!r.ok||data.error)throw new Error(data.error||"Data unavailable");return data}
async function load(){try{const [channel,data]=await Promise.all([getJson("channel.json"),getJson("data.json")]);renderChannel(channel);D=data;render()}catch(error){console.error(error);if(!D)$("#dateLabel").textContent="Live YouTube data is temporarily unavailable. Retrying automatically."}}
function init(){bind();load();setInterval(load,REFRESH_MS)}
function renderChannel(channel){if(!channel)return;$("#realtimeViews").textContent=fmt(channel.viewCount);$("#realtimeSubscribers").textContent=fmt(channel.subscriberCount);$("#realtimeVideos").textContent=fmt(channel.videoCount);const subscribers=Number(channel.subscriberCount)||0,target=1000,remaining=Math.max(0,target-subscribers);$("#goalValue").innerHTML=`${fmt(subscribers)} <span>/ ${fmt(target)}</span>`;$("#goalBar").style.width=Math.min(100,subscribers/target*100)+"%";$("#goalText").textContent=remaining?`${fmt(remaining)} more subscribers needed for the subscriber milestone.`:"Subscriber milestone reached!"}
function bind(){document.querySelectorAll(".range button").forEach(b=>b.onclick=()=>{document.querySelectorAll(".range button").forEach(x=>x.classList.remove("active"));b.classList.add("active");range=b.dataset.range;render()});$("#menuBtn").onclick=()=>{$("#sidebar").classList.toggle("open");$("#scrim").classList.toggle("open")};$("#scrim").onclick=()=>{$("#sidebar").classList.remove("open");$("#scrim").classList.remove("open")};$("#closeDialog").onclick=()=>$("#videoDialog").close()}
function selected(){if(range==="365")return D.daily;if(range==="90")return D.daily.slice(-90);if(range==="28")return D.daily.slice(-28);const m={};D.daily.forEach(r=>{const k=r[0].slice(0,7);m[k]??=[k,0,0,0,0];for(let i=1;i<5;i++)m[k][i]+=r[i]});return Object.values(m)}
function renderInsights(){const current=D.daily.slice(-28),previous=D.daily.slice(-56,-28),sum=(rows,i)=>rows.reduce((s,r)=>s+Number(r[i]||0),0),views=sum(current,1),oldViews=sum(previous,1),change=oldViews?(views-oldViews)*100/oldViews:0,avg=views?sum(current,2)*60/views:0,signal=$("#viewsSignal");signal.classList.toggle("positive",change>=0);signal.classList.toggle("warning",change<0);$("#viewsSignalIcon").textContent=change>=0?"↗":"↘";$("#viewsSignalTitle").textContent=change>=0?"Views are growing":"Views need attention";$("#viewsSignalText").textContent=`${change>=0?"Up":"Down"} ${Math.abs(change).toFixed(1)}% versus the previous 28 days.`;const retention=$("#retentionSignal"),good=avg>=60;retention.classList.toggle("positive",good);retention.classList.toggle("warning",!good);$("#retentionSignalTitle").textContent=good?"View duration is healthy":"Improve early retention";$("#retentionSignalText").textContent=`Current average duration is ${clock(avg)}. ${good?"Keep using the formats holding attention.":"Strengthen the first 15 seconds."}`}
function render(){if(!D)return;const rows=selected(),monthly=range==="month",views=rows.reduce((s,r)=>s+r[1],0),mins=rows.reduce((s,r)=>s+r[2],0),subs=rows.reduce((s,r)=>s+r[3]-r[4],0),avg=views?mins*60/views:0,last=D.daily.at(-1)?.[0]||"—";$("#dateLabel").textContent=(monthly?"Monthly totals":`Last ${range} days · through ${last}`)+` · synced ${new Date(D.syncedAt).toLocaleString("en-IN",{dateStyle:"medium",timeStyle:"short"})}`;$("#cards").innerHTML=[["Views",fmt(views)],["Watch time (hours)",fmt(mins/60)],["Subscribers",subs>0?"+"+fmt(subs):fmt(subs)],["Avg. view duration",clock(avg)]].map((x,i)=>`<article class="metric"><span>${x[0]}</span><strong>${x[1]}</strong><small>${i===0?"Verified analytics":i===2?"Net change":"Selected period"}</small></article>`).join("");if(D.channel)renderChannel(D.channel);renderInsights();$("#chartSub").textContent=monthly?"Monthly view totals":"Daily views in selected period";draw(rows.map(r=>({label:monthly?r[0]:r[0].slice(5),value:r[1]})));renderVideos();renderPopular()}
function draw(points){const c=$("#mainChart"),box=c.parentElement,tip=$("#tip"),dpr=devicePixelRatio||1,w=box.clientWidth,h=box.clientHeight;c.width=w*dpr;c.height=h*dpr;const x=c.getContext("2d");x.scale(dpr,dpr);const p={l:52,r:15,t:12,b:28},max=Math.max(1,...points.map(a=>a.value))*1.1,px=i=>p.l+i*(w-p.l-p.r)/Math.max(1,points.length-1),py=v=>h-p.b-v*(h-p.t-p.b)/max;x.clearRect(0,0,w,h);x.font="12px Arial";x.fillStyle="#707070";x.strokeStyle="#e8e8e8";for(let i=0;i<4;i++){const y=p.t+i*(h-p.t-p.b)/3;x.beginPath();x.moveTo(p.l,y);x.lineTo(w-p.r,y);x.stroke();x.fillText(fmt(max*(1-i/3)),3,y+4)}x.beginPath();points.forEach((a,i)=>i?x.lineTo(px(i),py(a.value)):x.moveTo(px(i),py(a.value)));x.strokeStyle="#065fd4";x.lineWidth=2;x.stroke();const step=Math.max(1,Math.ceil(points.length/5));points.forEach((a,i)=>{if(i%step===0||i===points.length-1)x.fillText(a.label,px(i)-12,h-6)});c.onmousemove=e=>{const r=c.getBoundingClientRect(),i=Math.max(0,Math.min(points.length-1,Math.round((e.clientX-r.left-p.l)/(w-p.l-p.r)*(points.length-1))));tip.style.left=px(i)+"px";tip.style.top=py(points[i].value)+"px";tip.textContent=points[i].label+" · "+fmt(points[i].value)+" views";tip.style.opacity=1};c.onmouseleave=()=>tip.style.opacity=0}
function renderVideos(){$("#videoList").innerHTML=D.videos.slice(0,5).map(v=>`<div class="video-row" data-id="${v.id}"><img src="${v.thumb}" alt=""><div class="v-title">${v.title}<span>${v.date}</span></div><div class="v-num"><b>${fmt(v.views)}</b><span>Views</span></div><div class="v-num retention"><b>${v.percent.toFixed(1)}%</b><span>Avg. viewed</span></div></div>`).join("");document.querySelectorAll(".video-row").forEach(e=>e.onclick=()=>detail(e.dataset.id))}
function renderPopular(){$("#popularGrid").innerHTML=D.popular.map(id=>{const v=D.videos.find(x=>x.id===id);return v?`<article class="pop-card" data-id="${id}"><img src="${v.thumb}" alt=""><h3>${v.title}</h3><p>${fmt(v.views)} views · ${v.percent.toFixed(1)}% viewed</p></article>`:""}).join("");document.querySelectorAll(".pop-card").forEach(e=>e.onclick=()=>detail(e.dataset.id))}
function detail(id){const v=D.videos.find(x=>x.id===id);if(v)window.openVideoAnalytics(v,"videoDialog","videoDetail")}
addEventListener("resize",()=>{clearTimeout(window.rt);window.rt=setTimeout(()=>D&&render(),150)});init();document.querySelector(".sidebar nav")?.insertAdjacentHTML("beforeend",'<a href="reports.html">▦ <span>Advanced reports</span></a><a href="planner.html">✓ <span>Content planner</span></a>');
